import{_ as n,a0 as i,w as p,s as u,I as s,x as o,a1 as l,A as r,ao as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"我愛開源的 7 個理由 | LCTT x X-CMD","titleTemplate":false,"description":"我愛開源的 7 個理由 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"我愛開源的 7 個理由 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"我愛開源的 7 個理由 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20181109 7 reasons I love open source","title":"我愛開源的 7 個理由","tag":"201811","desc":""},"relativePath":"201811/20181109 7 reasons I love open source.md","filePath":"[post].md"}'),d={name:"201811/20181109 7 reasons I love open source.md"};function m(f,t,g,T,C,b){const e=i("Link");return p(),u("div",null,[t[18]||(t[18]=s("h1",{id:"我愛開源的-7-個理由",tabindex:"-1"},[o("我愛開源的 7 個理由 "),s("a",{class:"header-anchor",href:"#我愛開源的-7-個理由","aria-label":"Permalink to “我愛開源的 7 個理由”"},"​")],-1)),t[19]||(t[19]=s("blockquote",null,[s("p",null,"成為開源社區的一員絕對是一個明智之舉，原因有很多。")],-1)),t[20]||(t[20]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/lead-images/BUSINESS_lovework.png?itok=gmj9tqiG",alt:""})],-1)),s("p",null,[t[1]||(t[1]=o("這就是我為什麼包括晚上和週末在內花費非常多的時間待在 ",-1)),l(e,{href:"https://github.com/ColinEberhardt/"},{default:r(()=>[...t[0]||(t[0]=[o("GitHub",-1)])]),_:1}),t[2]||(t[2]=o(" 上，成為開源社區的一個活躍成員。",-1))]),t[21]||(t[21]=a('<p>我參加過各種規模的項目，從個人項目到幾個人的協作項目，乃至有數百位貢獻者的項目，每一個項目都讓我有新的受益。</p><p><img src="https://opensource.com/sites/default/files/uploads/open_source_contributions.gif" alt=""></p><p>也就是説，這裏有七個原因讓我為開源做出貢獻：</p><ul><li><strong>它讓我的技能與時俱進。</strong> 在諮詢公司的管理職位工作，有時我覺得自己與創建軟件的實際過程越來越遠。參與開源項目使我可以重新回到我最熱愛的編程之中。也使我能夠體驗新技術，學習新技術和語言，並且使我不被酷酷的孩子們落下。</li><li><strong>它教我如何與人打交道。</strong> 與一羣素未謀面的人合作開源項目在與人交往方面能夠教會你很多。你很快會發現每個人有他們自己的壓力，他們自己的義務，以及不同的時間表。學習如何與一羣陌生人合作是一種很好的生活技能。</li><li><strong>它使我成為一個更好的溝通者。</strong> 開源項目的維護者的時間有限。你很快就知道，要成功地貢獻，你必須能夠清楚、簡明地表達你所做的改變、添加或修復，最重要的是，你為什麼要這麼做。</li><li><strong>它使我成為一個更好的開發者。</strong> 沒有什麼能像成百上千的其他開發者依賴你的代碼一樣 —— 它敦促你更加專注軟件設計、測試和文檔。</li><li><strong>它使我的造物變得更好。</strong> 可能開源背後最強大的觀念是它允許你駕馭一個由有創造力、有智慧、有知識的個人組成的全球網絡。我知道我自己一個人的能力是有限的，我不可能什麼都知道，但與開源社區的合作有助於我改進我的創作。</li><li><strong>它告訴我小事物的價值。</strong> 如果一個項目的文檔不清楚或不完整，我會毫不猶豫地把它做得更好。一個小小的更新或修復可能只節省開發人員幾分鐘的時間，但是隨着用户數量的增加，您一個小小的更改可能產生巨大的價值。</li><li><strong>它使我更好的營銷。</strong> 好的，這是一個奇怪的例子。有這麼多偉大的開源項目在那裏，感覺像一場爭奪關注的拼搏。從事於開源讓我學到了很多營銷的價值。這不是關於講述或創建一個華麗的網站。而是關於如何清楚地傳達你所創造的，它是如何使用的，以及它帶來的好處。</li></ul><p>我可以繼續討論開源是如何幫助你發展夥伴、關係和朋友的，不過你應該都知道了。有許多原因讓我樂於成為開源社區的一員。</p><p>你可能想知道這些如何用於大型金融服務機構的 IT 戰略。簡單來説：誰不想要一個擅長與人交流和工作，具有尖端的技能，並能夠推銷他們的成果的開發團隊呢？</p><hr>',7)),s("p",null,[t[4]||(t[4]=o("via: ",-1)),l(e,{href:"https://opensource.com/article/18/11/reasons-love-open-source"},{default:r(()=>[...t[3]||(t[3]=[o("https://opensource.com/article/18/11/reasons-love-open-source",-1)])]),_:1})]),s("p",null,[t[9]||(t[9]=o("作者：",-1)),l(e,{href:"https://opensource.com/users/colineberhardt"},{default:r(()=>[...t[5]||(t[5]=[o("Colin Eberhardt",-1)])]),_:1}),t[10]||(t[10]=o(" 選題：",-1)),l(e,{href:"https://github.com/lujun9972"},{default:r(()=>[...t[6]||(t[6]=[o("lujun9972",-1)])]),_:1}),t[11]||(t[11]=o(" 譯者：",-1)),l(e,{href:"https://github.com/ChiZelin"},{default:r(()=>[...t[7]||(t[7]=[o("ChiZelin",-1)])]),_:1}),t[12]||(t[12]=o(" 校對：",-1)),l(e,{href:"https://github.com/wxy"},{default:r(()=>[...t[8]||(t[8]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[15]||(t[15]=o("本文由 ",-1)),l(e,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[13]||(t[13]=[o("LCTT",-1)])]),_:1}),t[16]||(t[16]=o(" 原創編譯，",-1)),l(e,{href:"https://linux.cn/"},{default:r(()=>[...t[14]||(t[14]=[o("Linux中國",-1)])]),_:1}),t[17]||(t[17]=o(" 榮譽推出",-1))])])}const I=n(d,[["render",m]]);export{L as __pageData,I as default};
